    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "比率は9:16/16:9/1:1から選択可能です。解像度はプランごとに提供され、4KはSignatureまたはCustomプランでのみ選択できます。",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "配達日程: Starter 24～48時間、Pro 2～3営業日、Signature 3～5営業日基準です。画質、修正範囲、4Kかどうかに応じて変動することがあります。外貨表示は参考用で、実際の決済はウォン（KRW）に進みます。",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※AVVMは即座に自動生成ツールではなく、顧客イメージベースのカスタムデジタルコンテンツ制作サービスです。お支払い後の画像レビュー、AIドラフト作成、品質検収、最終納品順に行われます。",
