    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "Starterは24〜48時間、Proは営業日基準2〜3日、Signatureは営業日基準3〜5日以内に提供されます。",
