    "48시간 내 전달": "48時間以内に配信",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡パスポート、住民登録証、運転免許証などの公式身分証明書の写真は、各機関の審査基準によって承認の可否が異なる場合があります。 AVVMは、オリジナルの写真に基づいて、カスタムフィット、クロップ、容量調整、自然なキャリブレーションをサポートし、最終的な受付承認を保証しません。",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "他人の詐欺、アイデンティティの歪み、年齢の変更、顔の交換、実際の人物やその他のアイデンティティ作成目的の編集は行われません。撮影状態（焦点、照明、背景）が基準に大きく満たない原稿は製作が難しい場合があり、この場合全額返金されます。",
