    "서비스 제공 기간:": "サービス提供期間：",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "決済及び製作資料受付がすべて完了した時点から、Mini・Basic・Best Transform商品は営業日基準1～3日以内、3 Style Setは営業日基準3～7日以内、スターターは24～48時間、Proは営業日基準2～3日、Signatureは営業日基準3～5日以内提供されます。 MemorialおよびID・Profile商品は各商品カードに表示された24～48時間の提供期間が適用されます。お客様が提出した写真の品質、資料の補完、追加のリクエスト、または変更に応じてスケジュールが一部変動する場合があります。",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "アップロードした写真、ロゴ、商品画像、人物写真に対する使用権は受注者になければならず、他人詐称・身元歪み・無断商業利用目的の制作は進行しません。",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "映像はAI技術を活用して制作され、画質や要求スタイルによって結果が変わる場合があります。",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "アップロードする写真、ロゴ、商品画像、ポートレート写真へのアクセス権は、お客様ご自身で行う必要があります。",
