    "어떤 결과를 기대할 수 있는지 먼저 확인하세요. 모든 예시는 실제 입력 이미지와 AVVM 제작 결과를 나란히 보여줍니다.": "首先检查您可以期待什么结果。所有示例并排显示实际输入图像和 AVVM 生成结果。",
    "01": "01",
    "인물 에디토리얼": "人物社论",
