    "04": "04",
    "ID · 프로필": "身份·简介",
    "인물의 정체성은 유지하고, 배경·의상·조명을 프로필 목적에 맞게 정돈합니다.": "保持人物的身份，并安排背景、服装和灯光以适应个人资料的目的。",
