    "07": "07",
    "트래블 변신": "旅游转型",
    "인물 사진 한 장을 여행지와 스타일이 바뀌는 짧은 릴로 전환합니다.": "将单张肖像变成以旅行目的地和风格为特色的短卷轴。",
