    "CLEAN": "清洁",
    "WATER FILM.": "水膜。",
    "프리미엄 클렌징 오일 뷰티 샘플의 15초 광고 영상입니다. 물결, 투명한 라이트 블루 톤, 피부 클로즈업, 제품 중심 컷을 조합한 스킨케어 무드입니다.": "这是一段 15 秒的优质卸妆油美容样品广告视频。这是一种结合了波浪、透明浅蓝色调、皮肤特写和以产品为中心的剪裁的护肤氛围。",
    "15s Beauty Ad": "15s美容广告",
