    "DIRECTION FLOW": "方向流",
    "세련된 연출로 완성하는 15초 뷰티 광고": "15秒的美容广告，制作精良。",
    "TIME 00:00–00:05": "时间 00:00–00:05",
    "SCENE / CONTENT": "场景/内容",
    "맑은 물결 위에 제품이 등장하고, 투명한 블루 라이트가 첫인상을 만듭니다.": "产品呈现出清晰的波浪状，透明的蓝光营造出第一印象。",
    "VIDEO PROMPT": "视频提示",
    "유리 같은 반사광, 절제된 카메라 푸시인, 프리미엄 스킨케어 캠페인 무드.": "玻璃般的反射光、内敛的相机推入以及优质的护肤活动气氛。",
    "TIME 00:05–00:10": "时间 00:05–00:10",
    "물성과 피부 클로즈업이 이어지며, 깨끗한 사용감과 텍스처를 전달합니다.": "它将物理特性与皮肤特写相结合，提供干净的感觉和纹理。",
    "부드러운 슬로모션, 맑은 수분감, 고급 뷰티 필름의 리듬을 유지합니다.": "保持了高品质美颜片的流畅慢动作、清晰滋润、节奏感。",
    "TIME 00:10–00:15": "时间 00:10–00:15",
    "제품을 중심으로 정리된 엔드 프레임으로 브랜드 인상을 남깁니다.": "通过围绕产品组织的端架创造品牌印象。",
    "안정적인 제품 형태, 깨끗한 여백, 조용하지만 근사한 럭셔리 피니시.": "稳定的产品形式，干净的利润，安静但令人惊叹的奢华外观。",
