    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ AVVM不是即时自动创作工具，而是基于客户形象的定制化数字内容创作服务。付款后，流程经过图像审核、AI打稿、质量检验、最终交付。",
