    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "Starter 将在 24-48 小时内交付，Pro 将在 2-3 个工作日内交付，Signature 将在 3-5 个工作日内交付。",
