    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "时间表可能会根据客户提交的照片质量、材料补充、额外要求或修改而变化。如果预计会出现延误，我们将单独通知客户。",
