    "48시간 내 전달": "48小时内发货",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 护照、居民登记证、驾驶执照等官方证件照片的审批可能会因各机构的审查标准而有所不同。 AVVM支持基于原始照片的定制、裁剪、容量调整和自然校正，并且不保证最终提交的批准。",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "我们不会以冒充他人、歪曲身份、改变年龄、替换面孔或创造与真实人物不同的身份为目的进行编辑。拍摄条件（对焦、灯光、背景）明显低于标准的原稿可能难以制作，在这种情况下，我们将全额退款。",
