    "이 버튼은 카드사 심사용 KPN 테스트 결제창을 호출합니다. 운영 결제 완료 처리는 PG 승인 및 서버 검증 연동 후 활성화됩니다.": "此按钮调用 KPN 测试付款窗口以进行信用卡公司筛选。 PG批准并与服务器验证联动后，激活操作支付完成处理。",
    "결제 전 확인": "付款前确认",
    "본 상품은 고객 이미지 기반 맞춤 제작 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있습니다.": "该产品是根据客户图像定制的数字内容。生产开始后，因简单改变主意而取消和退款可能会受到限制。",
    "서비스 제공 기간:": "服务提供期限：",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "自付款及制作材料完成后，Mini·Basic·Best Transform产品将在1至3个工作日内交付，3个样式套装将在3至7个工作日内交付，Starter将在24至48小时内交付，Pro将在2至3个工作日内交付，Signature将在3至5个工作日内交付。 Memorial 和 ID·Profile 产品的优惠期为每张产品卡上注明的 24 至 48 小时。时间表可能会根据客户提交的照片质量、材料补充、额外要求或修改而变化。如果预计会出现延误，我们将单独通知客户。",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "订购者必须有权使用上传的照片、标志、产品图片和肖像，我们不得冒充他人、歪曲身份或将其制作用于未经授权的商业用途。",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "视频是使用人工智能技术制作的，结果可能会根据图像质量和要求的风格而有所不同。",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "客户必须获得使用上传的照片、徽标、产品图片和肖像的许可。",
    "ID·Profile 서비스는 제출용 규격 맞춤과 자연스러운 보정을 위한 서비스이며, 타인 사칭·신원 왜곡 목적의 편집은 진행하지 않습니다.": "ID/个人资料服务用于定制提交规范和自然更正，不涉及冒充他人或歪曲身份的编辑。",
    "[필수] 개인정보 수집·이용 동의": "[必填]同意收集和使用个人信息",
    "주문 처리 및 결과 안내를 위해 이름, 휴대폰번호, 이메일, 업로드 이미지, 주문 정보를 수집·이용하는 데 동의합니다.": "我同意收集和使用我的姓名、手机号码、电子邮件、上传的图像和订单信息用于订单处理和结果通知。",
    "[필수] 주문 진행 알림 수신 동의": "[必填] 同意接收订单进度通知",
    "주문 접수, 제작 진행, 완성 안내 등 거래 관련 정보를 카톡/문자/이메일로 받는 데 동의합니다.": "我同意通过KakaoTalk/短信/电子邮件接收交易相关信息，包括订单收据、生产进度和完成信息。",
    "[필수] 맞춤 제작 디지털 콘텐츠 및 환불 제한 동의": "[必填] 同意定制数字内容和退款限制",
    "본 상품은 고객이 제공한 이미지와 요청사항을 바탕으로 제작되는 맞춤형 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있음을 확인했습니다.": "该产品是根据客户提供的图像和请求创建的定制数字内容。我们已确认，在生产开始后，由于简单改变主意而导致的取消和退款可能会受到限制。",
