    "Quality": "Calidad",
    "Expert Final Review": "Revisión final de expertos",
    "Not instant automation. Better than that.": "No automatización instantánea. Mejor que eso.",
    "AI SPEED.": "VELOCIDAD DE LA IA.",
    "HUMAN FINISH.": "ACABADO HUMANO.",
    "AVVM은 “버튼을 누르자마자 무작위 결과가 나오는 자동툴”이 아닙니다. AI가 빠르게 영상 초안을 만들고, 사람이 상품성·브랜드감·시각적 오류를 확인해 주문 내용 확인 후 상업용 결과물로 납품하는 초고속 AI 제작 스튜디오입니다.": "AVVM no es una \"herramienta automática que produce resultados aleatorios tan pronto como presiona un botón\". Es un estudio de producción de IA de alta velocidad donde la IA crea rápidamente un borrador de video y los humanos verifican la calidad del producto, el sentido de la marca y los errores visuales, confirman el pedido y luego entregan el resultado comercial.",
    "Why “Vending Machine”?": "¿Por qué “máquina expendedora”?",
    "주문 방식은 자판기처럼 쉽고 빠르게. 결과물은 전문가 검수 후 납품합니다.": "Realizar pedidos es tan rápido y sencillo como en una máquina expendedora. Los resultados se entregan después de una inspección experta.",
    "Delivery Guide": "Guía de entrega",
    "AI 렌더링, 스타일 보정, 상품/로고 일관성 체크를 포함한 기본 납품 기준입니다.": "Criterios de entrega básicos que incluyen renderizado de IA, corrección de estilo y comprobaciones de coherencia del producto/logotipo.",
    "Realistic Expectation": "Expectativas realistas",
    "AI 결과는 이미지 품질과 스타일에 따라 달라질 수 있으며, 상업용 사용 전 최종 확인을 권장합니다.": "Los resultados de la IA pueden variar según la calidad y el estilo de la imagen; Se recomienda una verificación final antes del uso comercial.",
    "Commerce owners care about this most": "Los propietarios de comercios se preocupan más por esto",
    "KEEP THE": "MANTENGA EL",
    "PRODUCT RIGHT.": "DERECHO DE PRODUCTO.",
    "AI 영상에서 가장 큰 불안은 상품 로고, 라벨, 패키지 형태가 무너지는 문제입니다. AVVM은 제품 중심 광고에 맞게 상품 형태, 색감, 브랜드 인상, 라벨 가독성을 우선 검수합니다.": "La mayor preocupación con los vídeos de IA es el problema del colapso de los logotipos, las etiquetas y las formas de los paquetes de los productos. AVVM primero inspecciona la forma, el color, la impresión de marca y la legibilidad de la etiqueta del producto para adaptarlo a la publicidad centrada en el producto.",
    "Logo & Label Check": "Verificación de logotipo y etiqueta",
    "라벨·로고가 심하게 왜곡되면 재생성 또는 대체 컷으로 보정합니다.": "Si la etiqueta o el logotipo están muy distorsionados, corríjalos regenerándolos o reemplazándolos.",
    "Shape Preservation": "Preservación de la forma",
    "화장품 병, 패키지, 음식, 제품 실루엣이 원본과 다르게 보이지 않도록 확인합니다.": "Asegúrese de que las siluetas de botellas, paquetes, alimentos y productos de cosméticos no se vean diferentes del original.",
    "Commerce First": "Comercio primero",
    "예쁜 AI 영상보다 “팔리는 상품 영상”에 필요한 선명도와 신뢰감을 우선합니다.": "Priorizamos la claridad y la confianza necesarias para \"vender vídeos de productos\" a los bonitos vídeos de IA.",
    "LIVE PRE-FLIGHT": "PREVUELO EN VIVO",
    "YOUR SOURCE.": "TU FUENTE.",
    "CHECKED FIRST.": "COMPROBADO PRIMERO.",
    "사진을 업로드하면 해상도·노출·디테일을 먼저 점검하고, 선택한 화면비와 화질 기준으로 제작 방향을 결제 전에 확인합니다.": "Cuando carga una foto, primero verificamos la resolución, la exposición y los detalles, y confirmamos la dirección de producción según la relación de aspecto y la calidad seleccionadas antes del pago.",
    "CHECK MY PHOTO ↗": "MIRA MI FOTO ↗",
    "Show before payment": "Mostrar antes del pago",
    "TRY BEFORE": "PRUEBA ANTES",
    "FULL ORDER.": "PEDIDO COMPLETO.",
    "결과를 꾸며서 약속하지 않습니다. 먼저 원본의 제작 적합도와 실제 주문 규격을 보여주고, 이후 AI 렌더링과 전문가 검수를 거쳐 납품합니다.": "No prometemos resultados falsos. Primero, mostramos la idoneidad de la producción original y las especificaciones reales del pedido, y luego lo entregamos después de la representación de IA y la inspección de expertos.",
