    "잘 나온 사진 한 장만 올리세요. 평범한 일상 사진이 해외 명소, 인스타 감성, 패션 모델 무드로 바뀌는 초보자용 트랜스폼 영상입니다.": "Por favor sube sólo una buena foto. Este es un video de transformación para principiantes que transforma fotos cotidianas en lugares emblemáticos del extranjero, sensaciones de Instagram y estados de ánimo de modelos.",
    "01 · Travel Jump": "01 · Salto de viaje",
