    "앉아 있던 사진도 파리, 뉴욕, 산토리니, 도쿄 같은 글로벌 무드 영상으로 확장합니다.": "Las fotos de personas sentadas también se amplían a vídeos de estados de ánimo globales como París, Nueva York, Santorini y Tokio.",
    "02 · Fashion Switch": "02 · Cambio de moda",
    "옷차림을 모델룩으로": "Vestirse como modelo",
    "평범한 옷차림을 더 세련된 패션 화보 무드로 바꾸고, 헤어·신발·가방까지 스타일링합니다.": "Cambia tu atuendo habitual por un ambiente pictórico de moda más sofisticado e incluso peina tu cabello, zapatos y bolsos.",
    "03 · Walk Transform": "03 · Caminar Transformar",
    "걸으며 한순간에 변신": "Transfórmate en un instante mientras caminas",
    "보통 속도로 걷다가 가방을 뒤로 제끼고 고개를 돌리는 순간, 옷·악세서리·헤어·선글라스가 한 번에 바뀝니다.": "Mientras caminas a un ritmo normal, en el momento en que pones tu bolso detrás de ti y giras la cabeza, tu ropa, accesorios, cabello y gafas de sol cambian todo a la vez.",
