    "GET SET": "PREPÁRATE",
    "Hot Transform Styles": "Estilos de transformación calientes",
    "요즘 숏폼에서 잘 먹히는 전환 프롬프트를 고객이 쉽게 고를 수 있게 정리했습니다.": "Hemos recopilado mensajes de conversión que funcionan bien en formularios breves hoy en día para que los clientes puedan elegirlos fácilmente.",
    "Fashion Glow Up: 평범한 룩이 모델 같은 스타일로 변신": "Fashion Glow Up: transforma un look ordinario en un estilo de modelo",
