    "2회 수정 포함": "Incluye 2 revisiones",
    "해상도 선택: 1080p / 4K": "Seleccionar resolución: 1080p / 4K",
    "디렉터 스타일 감수": "Supervisión de estilo director",
    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "La relación se puede seleccionar entre 9:16 / 16:9 / 1:1. La resolución la proporciona el plan y 4K solo está disponible en los planes Signature o Custom.",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "Plazo de entrega: 24-48 horas para Starter, 2-3 días hábiles para Pro y 3-5 días hábiles para Signature. Puede variar según la calidad de la imagen, el rango de corrección y la disponibilidad de 4K. Las indicaciones en moneda extranjera son sólo como referencia; El pago real se realiza en won coreanos (KRW).",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ AVVM no es una herramienta de creación automática instantánea, sino un servicio de creación de contenido digital personalizado basado en imágenes de clientes. Después del pago, el proceso pasa por la revisión de la imagen, la creación del borrador de IA, la inspección de calidad y la entrega final.",
    "서비스 제공 기간": "Periodo de prestación del servicio",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 상품별 안내된 제작 기간 내 완성본을 제공합니다.": "Desde el momento en que se completa el pago y los materiales de producción, el producto terminado se proporcionará dentro del período de producción especificado para cada producto.",
    "Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내 제공됩니다.": "Los productos Mini·Basic·Best Transform se entregarán en un plazo de 1 a 3 días hábiles, y los 3 conjuntos de estilos se entregarán en un plazo de 3 a 7 días hábiles.",
    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "Starter se entregará en un plazo de 24 a 48 horas, Pro se entregará en un plazo de 2 a 3 días hábiles y Signature se entregará en un plazo de 3 a 5 días hábiles.",
    "Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Los productos Memorial y ID·Profile están sujetos a un periodo de oferta de 24 a 48 horas indicado en la ficha de cada producto.",
    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "El cronograma puede cambiar dependiendo de la calidad de las fotografías enviadas por el cliente, complementación de materiales, solicitudes adicionales o modificaciones. Si se esperan retrasos, los clientes serán notificados individualmente.",
    "다시 만나는 순간": "El momento en que nos volvamos a encontrar",
    "오래된 사진 속, 그리운 순간이 다시 움직입니다.": "En las fotografías antiguas los momentos nostálgicos vuelven a la vida.",
    "무지개다리를 건너간 반려동물, 빛바랜 필름 속 가족의 모습을 자연스러운 영상으로 복원해드립니다.": "Restauramos imágenes naturales de mascotas cruzando el puente arcoíris y familias capturadas en películas descoloridas.",
    "30년 전 깜순이 사진": "Una foto de Kamsuni de hace 30 años.",
