    "납기: 48시간 내 전달": "Plazo de entrega: entregado en 48 horas",
    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡 Debido a la naturaleza de la restauración de la IA, es posible que se exprese de manera diferente a su apariencia real y, si no le gusta, lo ayudaremos a recrearla una vez de acuerdo con los criterios del plan. Los resultados se entregan después de la inspección.",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "El cliente debe tener permiso para utilizar las fotografías cargadas de familiares, mascotas o personas fallecidas, y la producción puede restringirse para solicitudes que infrinjan los derechos de retrato, los derechos de autor o la reputación de un tercero.",
    "ID / Profile": "ID/Perfil",
    "증명사진·프로필사진 파일 제작": "Creación de archivos de foto de identificación y foto de perfil.",
