    "여권, 주민등록증, 운전면허, 이력서, 사원증, 프로필용까지 용도별 규격에 맞춘 JPG 파일로 제작해드립니다.": "Producimos archivos JPG adaptados a las especificaciones para cada propósito, incluidos pasaportes, tarjetas de registro de residentes, licencias de conducir, currículums, identificaciones de empleados y perfiles.",
