    "취업/사원증/비즈니스 고급 보정": "Empleo/ID de empleado/Corrección avanzada comercial",
    "피부, 대칭, 조명 등 1:1 디테일 고급 보정": "Corrección avanzada detallada 1:1 para piel, simetría, iluminación, etc.",
    "48시간 내 전달": "Entrega en 48 horas",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 La aprobación de fotografías de identificación oficial como pasaporte, tarjeta de registro de residente, licencia de conducir, etc. puede variar dependiendo de los estándares de evaluación de cada agencia. AVVM admite personalización, recorte, ajuste de capacidad y corrección natural según la fotografía original y no garantiza la aprobación final del envío.",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "No editamos con el fin de personificar a otra persona, distorsionar la identidad, cambiar la edad, reemplazar el rostro o crear una identidad diferente a la de la persona real. Los originales cuyas condiciones de disparo (enfoque, iluminación, fondo) estén significativamente por debajo de los estándares pueden resultar difíciles de producir, en cuyo caso se emitirá un reembolso completo.",
    "SISTER BRAND · WEB-STUDIO": "MARCA HERMANA · ESTUDIO WEB",
    "WATCH. JEWELRY.": "MIRA. JOYAS.",
    "LIFESTYLE.": "ESTILO DE VIDA.",
    "기본 로고 → 크리스털 로고 변환": "Logotipo básico → conversión de logotipo de cristal",
    "WEB-STUDIO는 시계, 주얼리, 라이프스타일 오브제를 하나의 감도로 큐레이션하는 자매 브랜드입니다. 홍보 영상으로 브랜드 무드를 먼저 만나보세요.": "WEB-STUDIO es una marca hermana que selecciona relojes, joyas y objetos de estilo de vida con una misma sensibilidad. Experimente primero el estado de ánimo de la marca a través del vídeo promocional.",
