    "사업자등록번호: 347-37-01807 · 통신판매업 신고번호: 제2026-경기파주-2862호": "Número de registro comercial: 347-37-01807 · Número de informe comercial de pedidos por correo: 2026-Gyeonggi Paju-2862",
    "대표 연락처: 0505-007-5221 · 이메일: airyoon72@naver.com · 도메인: avvm.studio": "Número de contacto del representante: 0505-007-5221 · Correo electrónico: airyoon72@naver.com · Dominio: avvm.studio",
