    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "Este servicio es un servicio personalizado de creación de contenido digital sin entrega física y el pago se procesa en won coreanos (KRW).",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Período de prestación del servicio: desde el momento en que se completan el pago y los materiales de producción, los productos Mini·Basic·Best Transform se proporcionarán en un plazo de 1 a 3 días hábiles, se proporcionarán 3 conjuntos de estilos en un plazo de 3 a 7 días hábiles, Starter se proporcionará en un plazo de 24 a 48 horas, Pro se proporcionará en un plazo de 2 a 3 días hábiles y Signature se proporcionará en un plazo de 3 a 5 días hábiles. Los productos Memorial y ID·Profile están sujetos a un periodo de oferta de 24 a 48 horas indicado en la ficha de cada producto.",
