    "결제 전 원본 사진의 제작 적합도를 확인합니다. 실제 결과는 선택한 스타일과 최종 검수에 따라 달라질 수 있습니다.": "Comprobamos la idoneidad de la fotografía original para la producción antes del pago. Los resultados reales pueden variar según el estilo seleccionado y la inspección final.",
    "2. 원하는 비디오 스타일 선택": "2. Elige el estilo de vídeo que desees",
    "첨부한 사진에 적용할 AI 연출 스타일 테마를 골라주세요.": "Seleccione el tema de estilo de producción de IA para aplicarlo a la foto adjunta.",
    "Beauty": "Belleza",
    "Product": "Producto",
    "Food": "comida",
    "Travel": "viajar",
    "Wedding": "boda",
    "Custom": "personalizado",
    "3. 완성본 수령 연락처 입력": "3. Ingrese la información de contacto para recibir la copia completa.",
    "제작 완료된 영상을 다운로드할 수 있는 이메일, 카톡 또는 문자 링크를 보내드립니다.": "Le enviaremos un correo electrónico, KakaoTalk o un enlace de texto para descargar el video completo.",
    "성함 / 브랜드명": "Nombre / Marca",
    "이메일 주소": "dirección de correo electrónico",
    "휴대폰 번호": "número de teléfono móvil",
    "현재는 PG 승인 전 테스트 모드입니다.": "Actualmente se encuentra en modo de prueba antes de la aprobación de PG.",
    "이 버튼은 카드사 심사용 KPN 테스트 결제창을 호출합니다. 운영 결제 완료 처리는 PG 승인 및 서버 검증 연동 후 활성화됩니다.": "Este botón abre la ventana de pago de prueba de KPN para la evaluación de la compañía de tarjetas de crédito. El procesamiento operativo de finalización del pago se activa después de la aprobación del PG y el enlace de verificación del servidor.",
    "결제 전 확인": "Confirmar antes del pago",
    "본 상품은 고객 이미지 기반 맞춤 제작 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있습니다.": "Este producto es contenido digital personalizado basado en imágenes de clientes. Una vez que comience la producción, es posible que se restrinjan las cancelaciones y los reembolsos debido a un simple cambio de opinión.",
    "서비스 제공 기간:": "Periodo de prestación del servicio:",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "Desde el momento en que se completen el pago y los materiales de producción, los productos Mini·Basic·Best Transform se entregarán dentro de 1 a 3 días hábiles, 3 Style Sets se entregarán dentro de 3 a 7 días hábiles, Starter se entregarán dentro de 24 a 48 horas, Pro se entregarán dentro de 2 a 3 días hábiles y Signature se entregarán dentro de 3 a 5 días hábiles. Los productos Memorial y ID·Profile están sujetos a un periodo de oferta de 24 a 48 horas indicado en la ficha de cada producto. El cronograma puede cambiar dependiendo de la calidad de las fotografías enviadas por el cliente, complementación de materiales, solicitudes adicionales o modificaciones. Si se esperan retrasos, los clientes serán notificados individualmente.",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "El cliente debe tener derecho a utilizar fotografías, logotipos, imágenes de productos y retratos cargados, y no nos hacemos pasar por otros, no distorsionamos identidades ni los producimos para uso comercial no autorizado.",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "Los videos se producen utilizando tecnología de inteligencia artificial y los resultados pueden variar según la calidad de la imagen y el estilo solicitado.",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "El cliente debe tener permiso para utilizar las fotografías, logotipos, imágenes de productos y retratos cargados.",
    "ID·Profile 서비스는 제출용 규격 맞춤과 자연스러운 보정을 위한 서비스이며, 타인 사칭·신원 왜곡 목적의 편집은 진행하지 않습니다.": "El servicio ID/Perfil sirve para personalizar las especificaciones de envío y las correcciones naturales, y no implica edición con el fin de hacerse pasar por otros o distorsionar la identidad.",
    "[필수] 개인정보 수집·이용 동의": "[Obligatorio] Consentimiento para la recopilación y el uso de información personal",
    "주문 처리 및 결과 안내를 위해 이름, 휴대폰번호, 이메일, 업로드 이미지, 주문 정보를 수집·이용하는 데 동의합니다.": "Acepto la recopilación y el uso de mi nombre, número de teléfono móvil, correo electrónico, imagen cargada e información del pedido para el procesamiento del pedido y la notificación de resultados.",
    "[필수] 주문 진행 알림 수신 동의": "[Obligatorio] Aceptar recibir notificaciones de progreso del pedido",
    "주문 접수, 제작 진행, 완성 안내 등 거래 관련 정보를 카톡/문자/이메일로 받는 데 동의합니다.": "Acepto recibir información relacionada con la transacción, incluido el recibo del pedido, el progreso de la producción y la información de finalización, a través de KakaoTalk/texto/correo electrónico.",
    "[필수] 맞춤 제작 디지털 콘텐츠 및 환불 제한 동의": "[Obligatorio] Acepte contenido digital personalizado y restricciones de reembolso",
    "본 상품은 고객이 제공한 이미지와 요청사항을 바탕으로 제작되는 맞춤형 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있음을 확인했습니다.": "Este producto es contenido digital personalizado creado en base a imágenes y solicitudes proporcionadas por el cliente. Hemos confirmado que la cancelación y los reembolsos debidos a un simple cambio de opinión pueden restringirse una vez que comience la producción.",
    "[필수] 이미지 사용 권한 및 초상권·저작권 확인": "[Obligatorio] Confirme los derechos de uso de imágenes, derechos de retrato y derechos de autor",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한이 본인에게 있으며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작을 요청하지 않음을 확인합니다.": "Confirmo que tengo derecho a utilizar las fotografías, logotipos, imágenes de productos y retratos que subo, y que no solicito su producción con el fin de hacerse pasar por otros, distorsionar mi identidad o utilizarlos con fines comerciales no autorizados.",
    "[선택] 마케팅 수신 동의": "[Opcional] Consentimiento para recibir marketing",
    "이벤트, 할인, 신규 샘플 안내 등 마케팅 정보를 카톡/문자/이메일로 받겠습니다.": "Recibirá información de marketing, como eventos, descuentos e información de nuevas muestras a través de KakaoTalk/texto/correo electrónico.",
