    "MVP 단계에서는 샘플 쇼릴과 주문 상담 기반으로 시작하고, 다음 단계에서는 무료 프리뷰 기능을 추가해 결제 전 확신을 높입니다.": "La etapa MVP comienza con un video de muestra y una consulta de pedidos, y en la siguiente etapa, se agrega una función de vista previa gratuita para aumentar la confianza antes del pago.",
