    "납기: 48시간 내 전달": "Délai de livraison : livré sous 48 heures",
    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡 En raison de la nature de la restauration de l'IA, elle peut être exprimée différemment de son apparence réelle, et si vous ne l'aimez pas, nous vous aiderons à la recréer une fois selon les critères du plan. Les résultats sont livrés après inspection.",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "Le client doit avoir l'autorisation d'utiliser les photos téléchargées de sa famille, de ses animaux domestiques ou du défunt, et la production peut être restreinte pour les demandes qui portent atteinte aux droits de portrait, aux droits d'auteur ou à la réputation d'un tiers.",
    "ID / Profile": "ID/Profil",
    "증명사진·프로필사진 파일 제작": "Création de fichiers de photos d'identité et de photos de profil",
