    "여권, 주민등록증, 운전면허, 이력서, 사원증, 프로필용까지 용도별 규격에 맞춘 JPG 파일로 제작해드립니다.": "Nous produisons des fichiers JPG adaptés aux spécifications de chaque objectif, notamment les passeports, les cartes d'enregistrement des résidents, les permis de conduire, les curriculum vitae, les cartes d'identité des employés et les profils.",
