    "취업/사원증/비즈니스 고급 보정": "Emploi/Carte d'identité de l'employé/Correction avancée de l'entreprise",
    "피부, 대칭, 조명 등 1:1 디테일 고급 보정": "Correction avancée détaillée 1:1 pour la peau, la symétrie, l'éclairage, etc.",
    "48시간 내 전달": "Livraison sous 48 heures",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 L'approbation des photos d'identité officielles telles que le passeport, la carte d'enregistrement du résident, le permis de conduire, etc. peut varier en fonction des normes de contrôle de chaque agence. AVVM prend en charge la personnalisation, le recadrage, l'ajustement de la capacité et la correction naturelle en fonction de la photo originale et ne garantit pas l'approbation finale de la soumission.",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "Nous ne modifions pas dans le but de usurper l'identité de quelqu'un d'autre, de déformer l'identité, de changer d'âge, de remplacer le visage ou de créer une identité différente de la personne réelle. Les originaux dont les conditions de prise de vue (mise au point, éclairage, arrière-plan) sont nettement inférieures aux normes peuvent être difficiles à produire, auquel cas un remboursement intégral sera effectué.",
    "SISTER BRAND · WEB-STUDIO": "MARQUE SŒUR · WEB-STUDIO",
