    "기본 로고 → 크리스털 로고 변환": "Logo de base → conversion du logo en cristal",
    "WEB-STUDIO는 시계, 주얼리, 라이프스타일 오브제를 하나의 감도로 큐레이션하는 자매 브랜드입니다. 홍보 영상으로 브랜드 무드를 먼저 만나보세요.": "WEB-STUDIO est une marque sœur qui sélectionne des montres, des bijoux et des objets de style de vie avec une seule sensibilité. Découvrez d'abord l'ambiance de la marque à travers la vidéo promotionnelle.",
