    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "Ce service est un service de création de contenu numérique personnalisé sans livraison physique, et le paiement est traité en won coréen (KRW).",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Période de fourniture du service : à partir du moment où le paiement et les matériaux de production sont terminés, les produits Mini·Basic·Best Transform seront fournis dans un délai de 1 à 3 jours ouvrables, 3 ensembles de styles seront fournis dans un délai de 3 à 7 jours ouvrables, Starter sera fourni dans un délai de 24 à 48 heures, Pro sera fourni dans un délai de 2 à 3 jours ouvrables et Signature sera fourni dans un délai de 3 à 5 jours ouvrables. Les produits Memorial et ID·Profile font l'objet d'une période d'offre de 24 à 48 heures indiquée sur chaque fiche produit.",
