    "이 버튼은 카드사 심사용 KPN 테스트 결제창을 호출합니다. 운영 결제 완료 처리는 PG 승인 및 서버 검증 연동 후 활성화됩니다.": "Ce bouton appelle la fenêtre de paiement test KPN pour la vérification des sociétés émettrices de cartes de crédit. Le traitement opérationnel de finalisation des paiements est activé après l'approbation du PG et la liaison de vérification du serveur.",
