    "본 상품은 고객 이미지 기반 맞춤 제작 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있습니다.": "Ce produit est un contenu numérique sur mesure basé sur les images des clients. Après le début de la production, les annulations et les remboursements dus à un simple changement d’avis peuvent être limités.",
    "서비스 제공 기간:": "Durée de prestation du service :",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "À partir du moment où le paiement et les matériaux de production sont terminés, les produits Mini·Basic·Best Transform seront livrés dans un délai de 1 à 3 jours ouvrables, 3 ensembles de styles seront livrés dans un délai de 3 à 7 jours ouvrables, Starter sera livré dans un délai de 24 à 48 heures, Pro sera livré dans un délai de 2 à 3 jours ouvrables et Signature sera livré dans un délai de 3 à 5 jours ouvrables. Les produits Memorial et ID·Profile font l'objet d'une période d'offre de 24 à 48 heures indiquée sur chaque fiche produit. Le planning peut évoluer en fonction de la qualité des photos soumises par le client, des compléments de matériel, des demandes supplémentaires ou des modifications. Si des retards sont attendus, les clients seront informés individuellement.",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "Le client doit avoir le droit d'utiliser les photos, logos, images de produits et portraits téléchargés, et nous ne usurpons pas l'identité d'autrui, ne déformons pas les identités et ne les produisons pas à des fins commerciales non autorisées.",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "Les vidéos sont produites à l'aide de la technologie d'IA et les résultats peuvent varier en fonction de la qualité de l'image et du style demandé.",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "Le client doit avoir l'autorisation d'utiliser les photos, logos, images de produits et portraits téléchargés.",
    "ID·Profile 서비스는 제출용 규격 맞춤과 자연스러운 보정을 위한 서비스이며, 타인 사칭·신원 왜곡 목적의 편집은 진행하지 않습니다.": "Le service ID/Profil sert à personnaliser les spécifications de soumission et les corrections naturelles, et n'implique pas de modification dans le but de usurper l'identité d'autrui ou de déformer l'identité.",
    "[필수] 개인정보 수집·이용 동의": "[Obligatoire] Consentement à la collecte et à l'utilisation d'informations personnelles",
    "주문 처리 및 결과 안내를 위해 이름, 휴대폰번호, 이메일, 업로드 이미지, 주문 정보를 수집·이용하는 데 동의합니다.": "J'accepte la collecte et l'utilisation de mon nom, de mon numéro de téléphone portable, de mon e-mail, de l'image téléchargée et des informations de commande pour le traitement de la commande et la notification des résultats.",
    "[필수] 주문 진행 알림 수신 동의": "[Obligatoire] Accepter de recevoir des notifications de progression de commande",
    "주문 접수, 제작 진행, 완성 안내 등 거래 관련 정보를 카톡/문자/이메일로 받는 데 동의합니다.": "J'accepte de recevoir des informations relatives aux transactions, y compris le reçu de commande, l'avancement de la production et les informations d'achèvement, via KakaoTalk/texte/e-mail.",
    "[필수] 맞춤 제작 디지털 콘텐츠 및 환불 제한 동의": "[Obligatoire] Accepter le contenu numérique créé sur mesure et les restrictions de remboursement",
    "본 상품은 고객이 제공한 이미지와 요청사항을 바탕으로 제작되는 맞춤형 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있음을 확인했습니다.": "Ce produit est un contenu numérique personnalisé créé à partir d'images et de demandes fournies par le client. Nous avons confirmé que les annulations et les remboursements dus à un simple changement d'avis peuvent être limités après le début de la production.",
    "[필수] 이미지 사용 권한 및 초상권·저작권 확인": "[Obligatoire] Confirmer les droits d'utilisation des images, les droits de portrait et les droits d'auteur",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한이 본인에게 있으며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작을 요청하지 않음을 확인합니다.": "Je confirme que j'ai le droit d'utiliser les photos, logos, images de produits et portraits que je télécharge, et que je n'en demande pas la production dans le but de usurper l'identité d'autrui, de déformer mon identité ou de les utiliser à des fins commerciales non autorisées.",
    "[선택] 마케팅 수신 동의": "[Facultatif] Consentement pour recevoir du marketing",
    "이벤트, 할인, 신규 샘플 안내 등 마케팅 정보를 카톡/문자/이메일로 받겠습니다.": "Vous recevrez des informations marketing telles que des événements, des réductions et de nouveaux exemples d'informations via KakaoTalk/texte/e-mail.",
