    "추후에는 자신의 상품 이미지를 올리면 저화질 워터마크 프리뷰를 빠르게 확인하고, 마음에 들 때 본 제작으로 이어지는 체험 공간을 제공할 예정입니다.": "À l'avenir, si vous téléchargez votre propre image de produit, nous fournirons un espace d'expérience où vous pourrez rapidement vérifier un aperçu d'un filigrane de mauvaise qualité et passer à la production si vous l'aimez.",
    "MVP 단계에서는 샘플 쇼릴과 주문 상담 기반으로 시작하고, 다음 단계에서는 무료 프리뷰 기능을 추가해 결제 전 확신을 높입니다.": "L'étape MVP commence par un exemple de showreel et une base de consultation des commandes, et à l'étape suivante, une fonction de prévisualisation gratuite est ajoutée pour accroître la confiance avant le paiement.",
