    "지역 문화 상징이 디지털 네트워크와 결합되는 메타버스형 영상 샘플입니다.": "Dabei handelt es sich um ein Videobeispiel im Metaversum-Stil, das lokale kulturelle Symbole mit digitalen Netzwerken kombiniert.",
