    "잘 나온 사진 한 장만 올리세요. 평범한 일상 사진이 해외 명소, 인스타 감성, 패션 모델 무드로 바뀌는 초보자용 트랜스폼 영상입니다.": "Bitte laden Sie nur ein gutes Foto hoch. Dies ist ein Transformationsvideo für Anfänger, das gewöhnliche Alltagsfotos in Wahrzeichen von Übersee, Instagram-Sensationen und Model-Stimmungen verwandelt.",
    "01 · Travel Jump": "01 · Reisesprung",
    "해외 명소로 순간 이동": "Teleportieren Sie sich zu Sehenswürdigkeiten in Übersee",
    "앉아 있던 사진도 파리, 뉴욕, 산토리니, 도쿄 같은 글로벌 무드 영상으로 확장합니다.": "Fotos von sitzenden Menschen werden auch zu globalen Stimmungsvideos wie Paris, New York, Santorini und Tokio erweitert.",
