    "보통 속도로 걷다가 가방을 뒤로 제끼고 고개를 돌리는 순간, 옷·악세서리·헤어·선글라스가 한 번에 바뀝니다.": "Beim Gehen in normalem Tempo verändern sich in dem Moment, in dem Sie Ihre Tasche hinter sich lassen und den Kopf drehen, Ihre Kleidung, Accessoires, Haare und Sonnenbrille auf einmal.",
