    "GET SET": "Machen Sie sich bereit",
    "Hot Transform Styles": "Heiße Transformationsstile",
    "요즘 숏폼에서 잘 먹히는 전환 프롬프트를 고객이 쉽게 고를 수 있게 정리했습니다.": "Wir haben Konvertierungsaufforderungen zusammengestellt, die heutzutage in Kurzform gut funktionieren, damit Kunden sie einfach auswählen können.",
    "Fashion Glow Up: 평범한 룩이 모델 같은 스타일로 변신": "Fashion Glow Up: Verwandeln Sie einen gewöhnlichen Look in einen Model-ähnlichen Stil",
