    "디렉터 스타일 감수": "Aufsicht im Stil eines Regisseurs",
    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "Das Verhältnis kann zwischen 9:16 / 16:9 / 1:1 gewählt werden. Die Auflösung wird durch den Plan bereitgestellt, und 4K ist nur in den Tarifen Signature oder Custom verfügbar.",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "Lieferzeit: 24–48 Stunden für Starter, 2–3 Werktage für Pro und 3–5 Werktage für Signature. Kann je nach Bildqualität, Korrekturbereich und 4K-Verfügbarkeit variieren. Fremdwährungsangaben dienen nur als Referenz; Die tatsächliche Zahlung erfolgt in koreanischen Won (KRW).",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ AVVM ist kein sofortiges automatisches Erstellungstool, sondern ein maßgeschneiderter Dienst zur Erstellung digitaler Inhalte basierend auf Kundenbildern. Nach der Zahlung durchläuft der Prozess die Bildüberprüfung, die Erstellung eines KI-Entwurfs, die Qualitätsprüfung und die endgültige Lieferung.",
    "서비스 제공 기간": "Zeitraum der Leistungserbringung",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 상품별 안내된 제작 기간 내 완성본을 제공합니다.": "Sobald die Zahlung und die Produktionsmaterialien abgeschlossen sind, wird das fertige Produkt innerhalb der für jedes Produkt angegebenen Produktionszeit bereitgestellt.",
    "Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내 제공됩니다.": "Mini·Basic·Best Transform-Produkte werden innerhalb von 1 bis 3 Werktagen geliefert, und 3 Style Sets werden innerhalb von 3 bis 7 Werktagen geliefert.",
    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "Starter wird innerhalb von 24–48 Stunden geliefert, Pro wird innerhalb von 2–3 Werktagen geliefert und Signature wird innerhalb von 3–5 Werktagen geliefert.",
    "Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Für Memorial- und ID·Profile-Produkte gilt ein Angebotszeitraum von 24 bis 48 Stunden, der auf jeder Produktkarte angegeben ist.",
    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "Der Zeitplan kann sich je nach Qualität der vom Kunden eingereichten Fotos, Ergänzung von Materialien, zusätzlichen Wünschen oder Änderungen ändern. Sollten Verzögerungen zu erwarten sein, werden die Kunden individuell benachrichtigt.",
    "다시 만나는 순간": "Der Moment, in dem wir uns wiedersehen",
    "오래된 사진 속, 그리운 순간이 다시 움직입니다.": "Auf alten Fotos werden nostalgische Momente wieder lebendig.",
    "무지개다리를 건너간 반려동물, 빛바랜 필름 속 가족의 모습을 자연스러운 영상으로 복원해드립니다.": "Wir stellen natürliche Bilder von Haustieren wieder her, die die Regenbogenbrücke überqueren, und von Familien, die in verblassten Filmen festgehalten wurden.",
    "30년 전 깜순이 사진": "Ein Foto von Kamsuni von vor 30 Jahren",
