    "사진 2장 세트 (추억을 더 풍성하게)": "Set mit 2 Fotos (bereichern Sie Ihre Erinnerungen)",
    "사진 2장으로 각각 다른 모션 영상 연출": "Erstellen Sie ein anderes Bewegungsvideo mit zwei Fotos",
    "납기: 48시간 내 전달": "Lieferzeit: Lieferung innerhalb von 48 Stunden",
    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡 Aufgrund der Natur der KI-Restaurierung kann es sein, dass sie anders aussieht als in Wirklichkeit, und wenn sie Ihnen nicht gefällt, helfen wir Ihnen, sie einmalig gemäß den Plankriterien neu zu erstellen. Die Ergebnisse werden nach Prüfung geliefert.",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "Der Kunde muss über die Erlaubnis verfügen, die hochgeladenen Fotos von Familienangehörigen, Haustieren oder Verstorbenen zu verwenden. Die Produktion kann für Anfragen eingeschränkt werden, die die Porträtrechte, das Urheberrecht oder den Ruf Dritter verletzen.",
    "ID / Profile": "ID/Profil",
    "증명사진·프로필사진 파일 제작": "Erstellung von Identifikationsfoto- und Profilfotodateien",
    "사진관 방문 없이, 기존 사진으로 제출용 사진 파일을 준비하세요.": "Bereiten Sie Fotodateien zur Einreichung vor, indem Sie vorhandene Fotos verwenden, ohne ein Fotostudio aufzusuchen.",
    "여권, 주민등록증, 운전면허, 이력서, 사원증, 프로필용까지 용도별 규격에 맞춘 JPG 파일로 제작해드립니다.": "Wir erstellen JPG-Dateien, die auf die Spezifikationen für jeden Zweck zugeschnitten sind, darunter Reisepässe, Einwohnermeldekarten, Führerscheine, Lebensläufe, Mitarbeiterausweise und Profile.",
