    "제출 목적별 4대 규격 전체 패키지": "Vollständiges Paket mit 4 Hauptspezifikationen für jeden Einreichungszweck",
    "Profile Pro": "Profil Pro",
    "취업/사원증/비즈니스 고급 보정": "Beschäftigung/Mitarbeiter-ID/Geschäftliche erweiterte Korrektur",
    "피부, 대칭, 조명 등 1:1 디테일 고급 보정": "1:1 detaillierte erweiterte Korrektur für Haut, Symmetrie, Beleuchtung usw.",
    "48시간 내 전달": "Lieferung innerhalb von 48 Stunden",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 Die Genehmigung offizieller Ausweisfotos wie Reisepass, Einwohnermeldekarte, Führerschein usw. kann je nach Überprüfungsstandards der einzelnen Behörden variieren. AVVM unterstützt die Anpassung, das Zuschneiden, die Kapazitätsanpassung und die natürliche Korrektur auf der Grundlage des Originalfotos und garantiert keine endgültige Genehmigung der Einreichung.",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "Wir bearbeiten nicht mit dem Ziel, sich als jemand anderes auszugeben, die Identität zu verzerren, das Alter zu ändern, das Gesicht zu ersetzen oder eine Identität zu schaffen, die sich von der tatsächlichen Person unterscheidet. Originale, deren Aufnahmebedingungen (Fokus, Beleuchtung, Hintergrund) deutlich unter den Standards liegen, können schwierig herzustellen sein. In diesem Fall wird eine volle Rückerstattung gewährt.",
    "SISTER BRAND · WEB-STUDIO": "SCHWESTERMARKE · WEB-STUDIO",
    "WATCH. JEWELRY.": "SEHEN. SCHMUCK.",
