    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "Bei diesem Service handelt es sich um einen maßgeschneiderten Service zur Erstellung digitaler Inhalte ohne physische Lieferung. Die Bezahlung erfolgt in koreanischen Won (KRW).",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Servicebereitstellungszeitraum: Ab dem Zeitpunkt, an dem die Zahlung und die Produktionsmaterialien abgeschlossen sind, werden Mini·Basic·Best Transform-Produkte innerhalb von 1 bis 3 Werktagen, 3 Style Sets innerhalb von 3 bis 7 Werktagen, Starter innerhalb von 24 bis 48 Stunden, Pro innerhalb von 2 bis 3 Werktagen und Signature innerhalb von 3 bis 5 Werktagen bereitgestellt. Für Memorial- und ID·Profile-Produkte gilt ein Angebotszeitraum von 24 bis 48 Stunden, der auf jeder Produktkarte angegeben ist.",
