    "BEAUTY · 9:16 · 1080P": "SCHÖNHEIT · 9:16 · 1080P",
    "결제 전 원본 사진의 제작 적합도를 확인합니다. 실제 결과는 선택한 스타일과 최종 검수에 따라 달라질 수 있습니다.": "Wir prüfen vor der Bezahlung die Eignung des Originalfotos für die Produktion. Die tatsächlichen Ergebnisse können je nach ausgewähltem Stil und Endkontrolle variieren.",
