    "제작 완료된 영상을 다운로드할 수 있는 이메일, 카톡 또는 문자 링크를 보내드립니다.": "Wir senden Ihnen eine E-Mail, KakaoTalk oder einen Textlink, um das fertige Video herunterzuladen.",
