    "현재는 PG 승인 전 테스트 모드입니다.": "Es befindet sich derzeit im Testmodus vor der PG-Genehmigung.",
    "이 버튼은 카드사 심사용 KPN 테스트 결제창을 호출합니다. 운영 결제 완료 처리는 PG 승인 및 서버 검증 연동 후 활성화됩니다.": "Über diese Schaltfläche wird das KPN-Testzahlungsfenster zur Überprüfung des Kreditkartenunternehmens aufgerufen. Die operative Zahlungsabwicklung wird nach der PG-Genehmigung und der Serververifizierungsverknüpfung aktiviert.",
    "결제 전 확인": "Vor der Zahlung bestätigen",
    "본 상품은 고객 이미지 기반 맞춤 제작 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있습니다.": "Bei diesem Produkt handelt es sich um maßgeschneiderte digitale Inhalte, die auf Kundenbildern basieren. Nach Produktionsbeginn können Stornierungen und Rückerstattungen aufgrund einer einfachen Meinungsänderung eingeschränkt sein.",
    "서비스 제공 기간:": "Zeitraum der Leistungserbringung:",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "Sobald die Zahlung und die Produktionsmaterialien abgeschlossen sind, werden Mini·Basic·Best Transform-Produkte innerhalb von 1 bis 3 Werktagen geliefert, 3 Style Sets werden innerhalb von 3 bis 7 Werktagen geliefert, Starter wird innerhalb von 24 bis 48 Stunden geliefert, Pro wird innerhalb von 2 bis 3 Werktagen geliefert und Signature wird innerhalb von 3 bis 5 Werktagen geliefert. Für Memorial- und ID·Profile-Produkte gilt ein Angebotszeitraum von 24 bis 48 Stunden, der auf jeder Produktkarte angegeben ist. Der Zeitplan kann sich je nach Qualität der vom Kunden eingereichten Fotos, Ergänzung von Materialien, zusätzlichen Wünschen oder Änderungen ändern. Sollten Verzögerungen zu erwarten sein, werden die Kunden individuell benachrichtigt.",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "Der Besteller muss das Recht haben, hochgeladene Fotos, Logos, Produktbilder und Porträts zu verwenden, und wir dürfen uns nicht als andere ausgeben, Identitäten verfälschen oder sie für eine unbefugte kommerzielle Nutzung produzieren.",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "Videos werden mit KI-Technologie produziert und die Ergebnisse können je nach Bildqualität und gewünschtem Stil variieren.",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "Zur Verwendung der hochgeladenen Fotos, Logos, Produktbilder und Porträts muss der Kunde berechtigt sein.",
    "ID·Profile 서비스는 제출용 규격 맞춤과 자연스러운 보정을 위한 서비스이며, 타인 사칭·신원 왜곡 목적의 편집은 진행하지 않습니다.": "Der ID-/Profildienst dient der individuellen Anpassung von Einreichungsspezifikationen und natürlichen Korrekturen und beinhaltet keine Bearbeitung mit dem Ziel, sich als andere auszugeben oder die Identität zu verfälschen.",
    "[필수] 개인정보 수집·이용 동의": "[Erforderlich] Zustimmung zur Erhebung und Nutzung personenbezogener Daten",
    "주문 처리 및 결과 안내를 위해 이름, 휴대폰번호, 이메일, 업로드 이미지, 주문 정보를 수집·이용하는 데 동의합니다.": "Ich stimme der Erfassung und Nutzung meines Namens, meiner Mobiltelefonnummer, meiner E-Mail-Adresse, meines hochgeladenen Bildes und meiner Bestellinformationen zur Bestellabwicklung und Ergebnisbenachrichtigung zu.",
    "[필수] 주문 진행 알림 수신 동의": "[Erforderlich] Stimmen Sie zu, Benachrichtigungen über den Bestellfortschritt zu erhalten",
    "주문 접수, 제작 진행, 완성 안내 등 거래 관련 정보를 카톡/문자/이메일로 받는 데 동의합니다.": "Ich bin damit einverstanden, transaktionsbezogene Informationen, einschließlich Auftragseingang, Produktionsfortschritt und Abschlussinformationen, per KakaoTalk/Text/E-Mail zu erhalten.",
    "[필수] 맞춤 제작 디지털 콘텐츠 및 환불 제한 동의": "[Erforderlich] Stimmen Sie individuell erstellten digitalen Inhalten und Rückerstattungsbeschränkungen zu",
    "본 상품은 고객이 제공한 이미지와 요청사항을 바탕으로 제작되는 맞춤형 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있음을 확인했습니다.": "Bei diesem Produkt handelt es sich um maßgeschneiderte digitale Inhalte, die auf der Grundlage von Bildern und Anfragen des Kunden erstellt werden. Wir haben bestätigt, dass Stornierungen und Rückerstattungen aufgrund einfacher Meinungsänderungen nach Produktionsbeginn eingeschränkt sein können.",
    "[필수] 이미지 사용 권한 및 초상권·저작권 확인": "[Erforderlich] Bestätigen Sie die Bildnutzungsrechte, Porträtrechte und das Urheberrecht",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한이 본인에게 있으며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작을 요청하지 않음을 확인합니다.": "Ich bestätige, dass ich das Recht habe, die von mir hochgeladenen Fotos, Logos, Produktbilder und Porträts zu verwenden, und dass ich nicht deren Produktion verlange, um mich als andere auszugeben, meine Identität zu verfälschen oder sie für unbefugte kommerzielle Zwecke zu verwenden.",
    "[선택] 마케팅 수신 동의": "[Optional] Einwilligung zum Erhalt von Marketing",
    "이벤트, 할인, 신규 샘플 안내 등 마케팅 정보를 카톡/문자/이메일로 받겠습니다.": "Sie erhalten Marketinginformationen wie Veranstaltungen, Rabatte und neue Probeninformationen per KakaoTalk/Text/E-Mail.",
