    "추후에는 자신의 상품 이미지를 올리면 저화질 워터마크 프리뷰를 빠르게 확인하고, 마음에 들 때 본 제작으로 이어지는 체험 공간을 제공할 예정입니다.": "Wenn Sie in Zukunft Ihr eigenes Produktbild hochladen, stellen wir Ihnen einen Erlebnisraum zur Verfügung, in dem Sie schnell eine Wasserzeichenvorschau mit geringer Qualität prüfen und bei Bedarf mit der Produktion fortfahren können.",
    "MVP 단계에서는 샘플 쇼릴과 주문 상담 기반으로 시작하고, 다음 단계에서는 무료 프리뷰 기능을 추가해 결제 전 확신을 높입니다.": "Die MVP-Phase beginnt mit einem Beispiel-Showreel und einer Bestellberatungsbasis. In der nächsten Phase wird eine kostenlose Vorschaufunktion hinzugefügt, um das Vertrauen vor der Zahlung zu erhöhen.",
    "7 SECTORS.": "7 SEKTOREN.",
