    "GET SET": "PREPARE-SE",
    "Hot Transform Styles": "Estilos de transformação a quente",
    "요즘 숏폼에서 잘 먹히는 전환 프롬프트를 고객이 쉽게 고를 수 있게 정리했습니다.": "Compilamos prompts de conversão que funcionam bem em formatos curtos atualmente, para que os clientes possam escolhê-los facilmente.",
    "Fashion Glow Up: 평범한 룩이 모델 같은 스타일로 변신": "Fashion Glow Up: Transforme um visual comum em um estilo de modelo",
    "World Travel Transform: 한 장의 사진이 전세계 명소 릴스로 변신": "World Travel Transform: Transforme uma única foto em um rolo de pontos de referência ao redor do mundo",
