    "디렉터 스타일 감수": "Supervisão de estilo de diretor",
    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "A proporção pode ser selecionada entre 9:16/16:9/1:1. A resolução é fornecida pelo plano e 4K está disponível apenas nos planos Assinatura ou Personalizado.",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "Cronograma de entrega: 24 a 48 horas para Starter, 2 a 3 dias úteis para Pro e 3 a 5 dias úteis para Signature. Pode variar dependendo da qualidade da imagem, faixa de correção e disponibilidade de 4K. As indicações de moeda estrangeira são apenas para referência; o pagamento real é feito em won coreano (KRW).",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ AVVM não é uma ferramenta de criação automática instantânea, mas um serviço personalizado de criação de conteúdo digital baseado em imagens de clientes. Após o pagamento, o processo passa por revisão de imagem, criação de rascunho de IA, inspeção de qualidade e entrega final.",
    "서비스 제공 기간": "Período de prestação de serviço",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 상품별 안내된 제작 기간 내 완성본을 제공합니다.": "A partir do momento em que o pagamento e os materiais de produção forem concluídos, o produto acabado será fornecido dentro do período de produção especificado para cada produto.",
    "Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내 제공됩니다.": "Os produtos Mini·Basic·Best Transform serão entregues dentro de 1 a 3 dias úteis, e 3 conjuntos de estilos serão entregues dentro de 3 a 7 dias úteis.",
    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "O Starter será entregue dentro de 24 a 48 horas, o Pro será entregue dentro de 2 a 3 dias úteis e o Signature será entregue dentro de 3 a 5 dias úteis.",
    "Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Os produtos Memorial e ID·Profile estão sujeitos a um período de oferta de 24 a 48 horas indicado na ficha de cada produto.",
    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "O cronograma poderá sofrer alterações dependendo da qualidade das fotos enviadas pelo cliente, complementação de materiais, solicitações adicionais ou modificações. Se houver previsão de atrasos, os clientes serão notificados individualmente.",
    "다시 만나는 순간": "No momento em que nos encontrarmos novamente",
    "오래된 사진 속, 그리운 순간이 다시 움직입니다.": "Em fotos antigas, momentos nostálgicos voltam à vida.",
    "무지개다리를 건너간 반려동물, 빛바랜 필름 속 가족의 모습을 자연스러운 영상으로 복원해드립니다.": "Restauramos imagens naturais de animais de estimação atravessando a ponte do arco-íris e famílias capturadas em filme desbotado.",
