    "사진 2장으로 각각 다른 모션 영상 연출": "Crie um vídeo em movimento diferente com duas fotos",
    "납기: 48시간 내 전달": "Prazo de entrega: entregue em 48 horas",
    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡 Devido à natureza da restauração da IA, ela pode ser expressa de forma diferente de sua aparência real e, se você não gostar, ajudaremos você a recriá-la uma vez, de acordo com os critérios do plano. Os resultados são entregues após inspeção.",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "O cliente deve ter permissão para usar as fotos enviadas de família, animais de estimação ou falecidos, e a produção pode ser restrita para solicitações que violem os direitos de retrato, direitos autorais ou reputação de terceiros.",
    "ID / Profile": "ID/Perfil",
    "증명사진·프로필사진 파일 제작": "Criação de arquivos de foto de identificação e foto de perfil",
    "사진관 방문 없이, 기존 사진으로 제출용 사진 파일을 준비하세요.": "Prepare arquivos de fotos para envio usando fotos existentes sem visitar um estúdio fotográfico.",
    "여권, 주민등록증, 운전면허, 이력서, 사원증, 프로필용까지 용도별 규격에 맞춘 JPG 파일로 제작해드립니다.": "Produzimos arquivos JPG adaptados às especificações de cada finalidade, incluindo passaportes, cartões de registro de residente, carteiras de motorista, currículos, carteiras de funcionários e perfis.",
