    "피부, 대칭, 조명 등 1:1 디테일 고급 보정": "Correção avançada detalhada 1:1 para pele, simetria, iluminação, etc.",
    "48시간 내 전달": "Entrega em 48 horas",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 A aprovação de fotos oficiais de identificação como passaporte, cartão de registro de residente, carteira de motorista, etc. pode variar dependendo dos padrões de triagem de cada agência. AVVM suporta personalização, corte, ajuste de capacidade e correção natural com base na foto original e não garante a aprovação final do envio.",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "Não editamos com o propósito de se passar por outra pessoa, distorcer identidade, mudar idade, substituir rosto ou criar uma identidade diferente da pessoa real. Originais cujas condições de filmagem (foco, iluminação, fundo) estejam significativamente abaixo dos padrões podem ser difíceis de produzir, caso em que será emitido um reembolso total.",
    "SISTER BRAND · WEB-STUDIO": "MARCA IRMÃ · WEB-STUDIO",
    "WATCH. JEWELRY.": "ASSISTA. JOIA.",
    "LIFESTYLE.": "ESTILO DE VIDA.",
    "기본 로고 → 크리스털 로고 변환": "Logotipo básico → conversão do logotipo de cristal",
    "WEB-STUDIO는 시계, 주얼리, 라이프스타일 오브제를 하나의 감도로 큐레이션하는 자매 브랜드입니다. 홍보 영상으로 브랜드 무드를 먼저 만나보세요.": "WEB-STUDIO é uma marca irmã que faz curadoria de relógios, joias e objetos de estilo de vida com uma sensibilidade. Experimente primeiro o clima da marca por meio do vídeo promocional.",
