    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "Este serviço é um serviço personalizado de criação de conteúdo digital sem entrega física e o pagamento é processado em Won Coreano (KRW).",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "Período de prestação do serviço: A partir do momento em que o pagamento e os materiais de produção forem concluídos, os produtos Mini·Basic·Best Transform serão fornecidos dentro de 1 a 3 dias úteis, 3 conjuntos de estilos serão fornecidos dentro de 3 a 7 dias úteis, o Starter será fornecido dentro de 24 a 48 horas, o Pro será fornecido dentro de 2 a 3 dias úteis e o Signature será fornecido dentro de 3 a 5 dias úteis. Os produtos Memorial e ID·Profile estão sujeitos a um período de oferta de 24 a 48 horas indicado na ficha de cada produto.",
