    "3. 완성본 수령 연락처 입력": "3. Insira as informações de contato para receber a cópia preenchida.",
    "제작 완료된 영상을 다운로드할 수 있는 이메일, 카톡 또는 문자 링크를 보내드립니다.": "Enviaremos a você um e-mail, KakaoTalk ou link de texto para baixar o vídeo completo.",
