    "현재는 PG 승인 전 테스트 모드입니다.": "Atualmente está em modo de teste antes da aprovação do PG.",
    "이 버튼은 카드사 심사용 KPN 테스트 결제창을 호출합니다. 운영 결제 완료 처리는 PG 승인 및 서버 검증 연동 후 활성화됩니다.": "Este botão abre a janela de pagamento de teste KPN para triagem da operadora de cartão de crédito. O processamento operacional de conclusão do pagamento é ativado após a aprovação do PG e a vinculação da verificação do servidor.",
    "결제 전 확인": "Confirme antes do pagamento",
    "본 상품은 고객 이미지 기반 맞춤 제작 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있습니다.": "Este produto é um conteúdo digital personalizado com base nas imagens dos clientes. Após o início da produção, o cancelamento e os reembolsos por simples mudança de ideia poderão ser restringidos.",
    "서비스 제공 기간:": "Período de prestação do serviço:",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다. 고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "A partir do momento em que o pagamento e os materiais de produção forem concluídos, os produtos Mini·Basic·Best Transform serão entregues dentro de 1 a 3 dias úteis, 3 conjuntos de estilo serão entregues dentro de 3 a 7 dias úteis, o Starter será entregue dentro de 24 a 48 horas, o Pro será entregue dentro de 2 a 3 dias úteis e o Signature será entregue dentro de 3 a 5 dias úteis. Os produtos Memorial e ID·Profile estão sujeitos a um período de oferta de 24 a 48 horas indicado na ficha de cada produto. O cronograma poderá sofrer alterações dependendo da qualidade das fotos enviadas pelo cliente, complementação de materiais, solicitações adicionais ou modificações. Se houver previsão de atrasos, os clientes serão notificados individualmente.",
    "업로드한 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 주문자에게 있어야 하며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작은 진행하지 않습니다.": "O comprador deve ter o direito de usar fotos, logotipos, imagens de produtos e retratos carregados, e não nos personificamos, distorcemos identidades ou os produzimos para uso comercial não autorizado.",
    "영상은 AI 기술을 활용하여 제작되며, 이미지 품질과 요청 스타일에 따라 결과가 달라질 수 있습니다.": "Os vídeos são produzidos com tecnologia de IA e os resultados podem variar dependendo da qualidade da imagem e do estilo solicitado.",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한은 고객 본인에게 있어야 합니다.": "O cliente deve ter permissão para usar as fotos, logotipos, imagens de produtos e retratos carregados.",
    "ID·Profile 서비스는 제출용 규격 맞춤과 자연스러운 보정을 위한 서비스이며, 타인 사칭·신원 왜곡 목적의 편집은 진행하지 않습니다.": "O serviço ID/Perfil destina-se à personalização de especificações de envio e correções naturais, e não envolve edição com o propósito de se passar por outra pessoa ou distorcer a identidade.",
    "[필수] 개인정보 수집·이용 동의": "[Obrigatório] Consentimento para coleta e uso de informações pessoais",
    "주문 처리 및 결과 안내를 위해 이름, 휴대폰번호, 이메일, 업로드 이미지, 주문 정보를 수집·이용하는 데 동의합니다.": "Concordo com a coleta e uso do meu nome, número de celular, e-mail, imagem carregada e informações do pedido para processamento do pedido e notificação de resultados.",
    "[필수] 주문 진행 알림 수신 동의": "[Obrigatório] Concorde em receber notificações de andamento do pedido",
    "주문 접수, 제작 진행, 완성 안내 등 거래 관련 정보를 카톡/문자/이메일로 받는 데 동의합니다.": "Concordo em receber informações relacionadas à transação, incluindo recebimento de pedidos, progresso da produção e informações de conclusão, via KakaoTalk/texto/e-mail.",
    "[필수] 맞춤 제작 디지털 콘텐츠 및 환불 제한 동의": "[Obrigatório] Concorde com conteúdo digital personalizado e restrições de reembolso",
    "본 상품은 고객이 제공한 이미지와 요청사항을 바탕으로 제작되는 맞춤형 디지털 콘텐츠입니다. 제작 착수 후에는 단순 변심에 의한 취소·환불이 제한될 수 있음을 확인했습니다.": "Este produto é um conteúdo digital customizado criado a partir de imagens e solicitações fornecidas pelo cliente. Confirmamos que cancelamentos e reembolsos por simples mudança de ideia poderão ser restringidos após o início da produção.",
    "[필수] 이미지 사용 권한 및 초상권·저작권 확인": "[Obrigatório] Confirme os direitos de uso da imagem, direitos de retrato e direitos autorais",
    "업로드하는 사진, 로고, 상품 이미지, 인물 사진에 대한 사용 권한이 본인에게 있으며, 타인 사칭·신원 왜곡·무단 상업 이용 목적의 제작을 요청하지 않음을 확인합니다.": "Confirmo que tenho o direito de usar as fotos, logotipos, imagens de produtos e retratos que carrego e que não solicito a produção dos mesmos com a finalidade de me passar por terceiros, distorcer minha identidade ou usá-los para fins comerciais não autorizados.",
