    "YOUR SOURCE.": "आपका स्रोत.",
    "CHECKED FIRST.": "पहले जांच की गई.",
    "사진을 업로드하면 해상도·노출·디테일을 먼저 점검하고, 선택한 화면비와 화질 기준으로 제작 방향을 결제 전에 확인합니다.": "जब आप कोई फोटो अपलोड करते हैं, तो हम पहले रिज़ॉल्यूशन, एक्सपोज़र और विवरण की जांच करते हैं, और भुगतान से पहले चयनित पहलू अनुपात और गुणवत्ता के आधार पर उत्पादन दिशा की पुष्टि करते हैं।",
    "CHECK MY PHOTO ↗": "मेरी फ़ोटो जांचें ↗",
    "Show before payment": "भुगतान से पहले दिखाएं",
    "TRY BEFORE": "पहले प्रयास करें",
    "FULL ORDER.": "पूर्ण आदेश.",
    "결과를 꾸며서 약속하지 않습니다. 먼저 원본의 제작 적합도와 실제 주문 규격을 보여주고, 이후 AI 렌더링과 전문가 검수를 거쳐 납품합니다.": "हम नकली परिणामों का वादा नहीं करते. सबसे पहले, हम मूल उत्पादन उपयुक्तता और वास्तविक ऑर्डर विनिर्देश दिखाते हैं, और फिर एआई रेंडरिंग और विशेषज्ञ निरीक्षण के बाद इसे वितरित करते हैं।",
    "Portfolio expansion": "पोर्टफोलियो विस्तार",
    "9 SECTORS.": "9 सेक्टर.",
    "ONE ENGINE.": "एक इंजन.",
    "AVVM은 뷰티, 자동차, 문화, 기업, 축제, 스토리, 메타버스, 뮤직비디오, 액션까지 9개 산업군의 영상 샘플로 확장됩니다.": "एवीवीएम सौंदर्य, ऑटोमोबाइल, संस्कृति, कंपनियों, त्योहारों, कहानियों, मेटावर्स, संगीत वीडियो और एक्शन सहित 9 उद्योगों के वीडियो नमूनों तक विस्तारित है।",
    "AUTOMOTIVE": "मोटर वाहन",
    "F1 AERIAL DRIVE": "F1 हवाई ड्राइव",
    "공중 추적, 고속 코너링, 레이스 에너지를 보여주는 자동차 섹터 샘플입니다.": "हवाई ट्रैकिंग, हाई-स्पीड कॉर्नरिंग और रेस ऊर्जा का प्रदर्शन करने वाले ऑटोमोटिव क्षेत्र का एक नमूना।",
