    "디렉터 스타일 감수": "निदेशक शैली पर्यवेक्षण",
    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "अनुपात 9:16 / 16:9 / 1:1 से चुना जा सकता है। रिज़ॉल्यूशन प्लान द्वारा प्रदान किया जाता है, और 4K केवल सिग्नेचर या कस्टम प्लान में उपलब्ध है।",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "डिलीवरी शेड्यूल: स्टार्टर के लिए 24-48 घंटे, प्रो के लिए 2-3 कार्यदिवस और सिग्नेचर के लिए 3-5 कार्यदिवस। छवि गुणवत्ता, सुधार सीमा और 4K उपलब्धता के आधार पर भिन्न हो सकता है। विदेशी मुद्रा संकेत केवल संदर्भ के लिए हैं; वास्तविक भुगतान कोरियाई वोन (KRW) में किया जाता है।",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ एवीवीएम एक त्वरित स्वचालित निर्माण उपकरण नहीं है, बल्कि ग्राहक छवियों के आधार पर एक अनुकूलित डिजिटल सामग्री निर्माण सेवा है। भुगतान के बाद, प्रक्रिया छवि समीक्षा, एआई ड्राफ्ट निर्माण, गुणवत्ता निरीक्षण और अंतिम वितरण से गुजरती है।",
    "서비스 제공 기간": "सेवा प्रावधान अवधि",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 상품별 안내된 제작 기간 내 완성본을 제공합니다.": "भुगतान और उत्पादन सामग्री पूरी होने के समय से, तैयार उत्पाद प्रत्येक उत्पाद के लिए निर्दिष्ट उत्पादन अवधि के भीतर प्रदान किया जाएगा।",
    "Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내 제공됩니다.": "मिनी·बेसिक·बेस्ट ट्रांसफॉर्म उत्पाद 1 से 3 व्यावसायिक दिनों के भीतर वितरित किए जाएंगे, और 3 स्टाइल सेट 3 से 7 व्यावसायिक दिनों के भीतर वितरित किए जाएंगे।",
    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "स्टार्टर 24-48 घंटों के भीतर वितरित किया जाएगा, प्रो 2-3 व्यावसायिक दिनों के भीतर वितरित किया जाएगा, और सिग्नेचर 3-5 व्यावसायिक दिनों के भीतर वितरित किया जाएगा।",
    "Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "मेमोरियल और आईडी·प्रोफ़ाइल उत्पाद प्रत्येक उत्पाद कार्ड पर दर्शाई गई 24 से 48 घंटे की ऑफ़र अवधि के अधीन हैं।",
    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "ग्राहक द्वारा सबमिट की गई तस्वीरों की गुणवत्ता, सामग्री के पूरक, अतिरिक्त अनुरोध या संशोधनों के आधार पर शेड्यूल बदल सकता है। यदि देरी की आशंका है, तो ग्राहकों को व्यक्तिगत रूप से सूचित किया जाएगा।",
    "다시 만나는 순간": "जिस पल हम दोबारा मिलेंगे",
