    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡एआई बहाली की प्रकृति के कारण, इसे इसके वास्तविक स्वरूप से भिन्न रूप से व्यक्त किया जा सकता है, और यदि आपको यह पसंद नहीं है, तो हम योजना मानदंडों के अनुसार इसे एक बार फिर से बनाने में आपकी सहायता करेंगे। निरीक्षण के बाद परिणाम दिए जाते हैं।",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "ग्राहक के पास परिवार, पालतू जानवर या मृतक की अपलोड की गई तस्वीरों का उपयोग करने की अनुमति होनी चाहिए, और उन अनुरोधों के लिए उत्पादन प्रतिबंधित किया जा सकता है जो पोर्ट्रेट अधिकार, कॉपीराइट, या किसी तीसरे पक्ष की प्रतिष्ठा का उल्लंघन करते हैं।",
    "ID / Profile": "आईडी/प्रोफ़ाइल",
