    "사진관 방문 없이, 기존 사진으로 제출용 사진 파일을 준비하세요.": "किसी फोटो स्टूडियो में गए बिना मौजूदा फ़ोटो का उपयोग करके प्रस्तुत करने के लिए फ़ोटो फ़ाइलें तैयार करें।",
    "여권, 주민등록증, 운전면허, 이력서, 사원증, 프로필용까지 용도별 규격에 맞춘 JPG 파일로 제작해드립니다.": "हम पासपोर्ट, निवासी पंजीकरण कार्ड, ड्राइवर का लाइसेंस, बायोडाटा, कर्मचारी आईडी और प्रोफाइल सहित प्रत्येक उद्देश्य के लिए विशिष्टताओं के अनुरूप जेपीजी फाइलें तैयार करते हैं।",
