    "48시간 내 전달": "48 घंटे के अंदर डिलिवरी",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 पासपोर्ट, निवासी पंजीकरण कार्ड, ड्राइवर का लाइसेंस इत्यादि जैसी आधिकारिक आईडी फ़ोटो की स्वीकृति प्रत्येक एजेंसी के स्क्रीनिंग मानकों के आधार पर भिन्न हो सकती है। एवीवीएम मूल फोटो के आधार पर अनुकूलन, क्रॉपिंग, क्षमता समायोजन और प्राकृतिक सुधार का समर्थन करता है और अंतिम सबमिशन अनुमोदन की गारंटी नहीं देता है।",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "हम किसी और का प्रतिरूपण करने, पहचान विकृत करने, उम्र बदलने, चेहरा बदलने या वास्तविक व्यक्ति से अलग पहचान बनाने के उद्देश्य से संपादन नहीं करते हैं। मूल जिनकी शूटिंग की स्थिति (फ़ोकस, प्रकाश व्यवस्था, पृष्ठभूमि) मानकों से काफी नीचे है, उनका उत्पादन करना मुश्किल हो सकता है, ऐसी स्थिति में पूर्ण धन-वापसी जारी की जाएगी।",
