    "사업자등록번호: 347-37-01807 · 통신판매업 신고번호: 제2026-경기파주-2862호": "व्यवसाय पंजीकरण संख्या: 347-37-01807 · मेल ऑर्डर व्यवसाय रिपोर्ट संख्या: 2026-ग्योंगगी पाजू-2862",
