    "사업장 주소: 경기도 파주시 미래로310번길 182-37 B동 2층 02호": "व्यवसाय का पता: कमरा 02, बिल्डिंग बी, दूसरी मंजिल, 182-37 मिराए-आरओ 310बीऑन-गिल, पाजू-सी, ग्योंगगी-डो",
    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "यह सेवा भौतिक वितरण के बिना एक अनुकूलित डिजिटल सामग्री निर्माण सेवा है, और भुगतान कोरियाई वोन (केआरडब्ल्यू) में संसाधित किया जाता है।",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "सेवा प्रावधान अवधि: भुगतान और उत्पादन सामग्री पूरी होने के समय से, मिनी·बेसिक·बेस्ट ट्रांसफॉर्म उत्पाद 1 से 3 व्यावसायिक दिनों के भीतर प्रदान किए जाएंगे, 3 स्टाइल सेट 3 से 7 व्यावसायिक दिनों के भीतर प्रदान किए जाएंगे, स्टार्टर 24 से 48 घंटों के भीतर प्रदान किए जाएंगे, प्रो 2 से 3 व्यावसायिक दिनों के भीतर प्रदान किए जाएंगे, और हस्ताक्षर 3 से 5 व्यावसायिक दिनों के भीतर प्रदान किए जाएंगे। मेमोरियल और आईडी·प्रोफ़ाइल उत्पाद प्रत्येक उत्पाद कार्ड पर दर्शाई गई 24 से 48 घंटे की ऑफ़र अवधि के अधीन हैं।",
    "결제대행 및 개인정보 처리 위탁: 주식회사 코리아포트원(전자결제 서비스 제공, 결제 처리, 결제 결과 확인 및 정산 업무)": "भुगतान एजेंसी और व्यक्तिगत सूचना प्रसंस्करण सौंपा गया: कोरिया पोर्ट वन कंपनी लिमिटेड (इलेक्ट्रॉनिक भुगतान सेवा प्रावधान, भुगतान प्रसंस्करण, भुगतान परिणाम की पुष्टि और निपटान)",
