    "스타트 버튼을 누른 뒤 바로 결제 정보가 아니라, 원하는 상품을 먼저 고르는 흐름입니다.": "स्टार्ट बटन दबाने के बाद, आप भुगतान जानकारी दर्ज करने के बजाय सबसे पहले अपने इच्छित उत्पाद का चयन करें।",
