    "여권/주민등록증/면허/이력서 중 1종": "निम्नलिखित में से एक: पासपोर्ट/निवासी पंजीकरण कार्ड/लाइसेंस/बायोडाटा",
    "4대 규격 전체 패키지 (여권/주민증/면허/이력서)": "4 प्रमुख विशिष्टताओं का पूरा पैकेज (पासपोर्ट/निवासी कार्ड/लाइसेंस/रेज़्यूमे)",
    "PRO": "प्रो",
    "Selected plan: Pro · ₩39,900": "चयनित योजना: प्रो · ₩39,900",
    "1. 제작할 사진 업로드": "1. वह फोटो अपलोड करें जिसे आप बनाना चाहते हैं",
    "고객님의 사진 또는 상품 이미지를 첨부해 주세요. 지금 첨부하지 않아도 결제 후 업로드할 수 있습니다.": "कृपया अपना फोटो या उत्पाद छवि संलग्न करें। भले ही आप इसे अभी संलग्न न करें, भुगतान के बाद इसे अपलोड कर सकते हैं।",
    "사진 첨부하기": "एक फोटो संलग्न करें",
