    "여권용 가이드:": "पासपोर्ट गाइड:",
    "정면·무배경·귀가 보이게 촬영된 사진을 올려주세요.": "कृपया सामने से लिया गया फोटो अपलोड करें, जिसमें कोई पृष्ठभूमि न हो और कान दिखाई न दे।",
