    "Not instant automation. Better than that.": "ليست أتمتة فورية. أفضل من ذلك.",
    "AI SPEED.": "سرعة الذكاء الاصطناعي.",
    "HUMAN FINISH.": "النهاية البشرية.",
    "AVVM은 “버튼을 누르자마자 무작위 결과가 나오는 자동툴”이 아닙니다. AI가 빠르게 영상 초안을 만들고, 사람이 상품성·브랜드감·시각적 오류를 확인해 주문 내용 확인 후 상업용 결과물로 납품하는 초고속 AI 제작 스튜디오입니다.": "AVVM ليست \"أداة تلقائية تنتج نتائج عشوائية بمجرد الضغط على زر\". إنه استوديو إنتاج عالي السرعة يعمل بالذكاء الاصطناعي، حيث يقوم الذكاء الاصطناعي بإنشاء مسودة فيديو بسرعة، ويقوم البشر بفحص جودة المنتج، والشعور بالعلامة التجارية، والأخطاء البصرية، وتأكيد الطلب، ثم تسليم النتيجة التجارية.",
    "Why “Vending Machine”?": "لماذا \"آلة البيع\"؟",
    "주문 방식은 자판기처럼 쉽고 빠르게. 결과물은 전문가 검수 후 납품합니다.": "الطلب سريع وسهل مثل آلة البيع. يتم تسليم النتائج بعد فحص الخبراء.",
    "Delivery Guide": "دليل التسليم",
    "AI 렌더링, 스타일 보정, 상품/로고 일관성 체크를 포함한 기본 납품 기준입니다.": "معايير التسليم الأساسية بما في ذلك عرض الذكاء الاصطناعي وتصحيح النمط والتحقق من اتساق المنتج/الشعار.",
    "Realistic Expectation": "توقعات واقعية",
    "AI 결과는 이미지 품질과 스타일에 따라 달라질 수 있으며, 상업용 사용 전 최종 확인을 권장합니다.": "قد تختلف نتائج الذكاء الاصطناعي حسب جودة الصورة وأسلوبها؛ يوصى بالتحقق النهائي قبل الاستخدام التجاري.",
    "Commerce owners care about this most": "يهتم أصحاب التجارة بهذا الأمر أكثر من غيرهم",
    "KEEP THE": "احتفظ بـ",
    "PRODUCT RIGHT.": "حق المنتج.",
    "AI 영상에서 가장 큰 불안은 상품 로고, 라벨, 패키지 형태가 무너지는 문제입니다. AVVM은 제품 중심 광고에 맞게 상품 형태, 색감, 브랜드 인상, 라벨 가독성을 우선 검수합니다.": "أكبر ما يثير القلق بشأن مقاطع فيديو الذكاء الاصطناعي هو مشكلة انهيار شعارات المنتجات وملصقاتها وأشكال العبوات. تقوم AVVM أولاً بفحص شكل المنتج ولونه وانطباع العلامة التجارية وإمكانية قراءة الملصق بما يتناسب مع الإعلانات التي تركز على المنتج.",
    "Logo & Label Check": "التحقق من الشعار والتسمية",
    "라벨·로고가 심하게 왜곡되면 재생성 또는 대체 컷으로 보정합니다.": "إذا كان الملصق أو الشعار مشوهًا بشدة، فقم بتصحيحه عن طريق تجديده أو استبداله.",
    "Shape Preservation": "الحفاظ على الشكل",
    "화장품 병, 패키지, 음식, 제품 실루엣이 원본과 다르게 보이지 않도록 확인합니다.": "تأكد من أن صور زجاجات مستحضرات التجميل والعبوات والمواد الغذائية والمنتجات لا تبدو مختلفة عن الأصل.",
    "Commerce First": "التجارة أولا",
    "예쁜 AI 영상보다 “팔리는 상품 영상”에 필요한 선명도와 신뢰감을 우선합니다.": "نحن نعطي الأولوية للوضوح والثقة المطلوبة \"لبيع مقاطع فيديو المنتج\" على مقاطع فيديو الذكاء الاصطناعي الجميلة.",
    "LIVE PRE-FLIGHT": "بث مباشر قبل الرحلة",
