    "사진을 업로드하면 해상도·노출·디테일을 먼저 점검하고, 선택한 화면비와 화질 기준으로 제작 방향을 결제 전에 확인합니다.": "عندما تقوم بتحميل صورة، نتحقق أولاً من الدقة والتعرض والتفاصيل، ونؤكد اتجاه الإنتاج بناءً على نسبة العرض إلى الارتفاع والجودة المحددة قبل الدفع.",
    "CHECK MY PHOTO ↗": "تحقق من صورتي ↗",
    "Show before payment": "عرض قبل الدفع",
    "TRY BEFORE": "حاول من قبل",
    "FULL ORDER.": "الطلب الكامل.",
    "결과를 꾸며서 약속하지 않습니다. 먼저 원본의 제작 적합도와 실제 주문 규격을 보여주고, 이후 AI 렌더링과 전문가 검수를 거쳐 납품합니다.": "نحن لا نعد بنتائج وهمية. أولاً، نعرض مدى ملاءمة الإنتاج الأصلي ومواصفات الطلب الفعلية، ثم نقوم بتسليمها بعد تقديم الذكاء الاصطناعي وفحص الخبراء.",
    "Portfolio expansion": "توسيع المحفظة",
    "9 SECTORS.": "9 قطاعات.",
    "ONE ENGINE.": "محرك واحد.",
    "AVVM은 뷰티, 자동차, 문화, 기업, 축제, 스토리, 메타버스, 뮤직비디오, 액션까지 9개 산업군의 영상 샘플로 확장됩니다.": "يتوسع AVVM ليشمل عينات فيديو من 9 صناعات، بما في ذلك الجمال والسيارات والثقافة والشركات والمهرجانات والقصص والميتافيرس ومقاطع الفيديو الموسيقية والحركة.",
