    "전통 장인성과 미래 기술 이미지를 결합한 문화/관광 영상 샘플입니다.": "هذه عينة فيديو ثقافية/سياحية تجمع بين الحرف اليدوية التقليدية وصور التكنولوجيا المستقبلية.",
    "BUSINESS": "عمل",
    "CORPORATE FILM": "فيلم الشركات",
    "기업, 서비스, 스타트업 소개에 맞는 짧은 비즈니스 영상 샘플입니다.": "هذه عينة فيديو قصيرة للأعمال مناسبة للتعريف بالشركات والخدمات والشركات الناشئة.",
