    "METAVERSE": "ميتافيرس",
    "CULTURE NETWORK": "شبكة الثقافة",
    "지역 문화 상징이 디지털 네트워크와 결합되는 메타버스형 영상 샘플입니다.": "هذه عينة فيديو من النوع metaverse تجمع بين الرموز الثقافية المحلية والشبكات الرقمية.",
    "MUSIC VIDEO": "فيديو موسيقي",
    "DANCE PERFORMANCE": "أداء الرقص",
    "무대 퍼포먼스와 리듬감 있는 카메라 무브먼트를 담은 뮤직비디오 샘플입니다.": "هذه عينة فيديو موسيقي تتميز بالأداء المسرحي وحركة الكاميرا الإيقاعية.",
    "ACTION": "العمل",
    "EXPERIMENTAL ACTION": "العمل التجريبي",
    "격투, 추격, 긴장감 있는 전환을 보여주는 실험적 액션 영상 샘플입니다.": "هذه عينة فيديو تجريبية تظهر القتال والمطاردات والتحولات المتوترة.",
