    "INCLUDED?": "متضمن؟",
    "영상 길이와 화질 외에도 커머스 영상에 필요한 BGM, 효과음, 자막, 카피, 보이스 여부를 명확히 안내합니다.": "بالإضافة إلى طول الفيديو وجودته، نقدم إرشادات واضحة حول BGM والمؤثرات الصوتية والترجمات والنسخ والصوت المطلوب لمقاطع الفيديو التجارية.",
