    "For everyone · sticker-photo price": "للجميع سعر ملصق الصورة",
    "ONE PHOTO,": "صورة واحدة،",
    "NEW WORLD.": "عالم جديد.",
    "잘 나온 사진 한 장만 올리세요. 평범한 일상 사진이 해외 명소, 인스타 감성, 패션 모델 무드로 바뀌는 초보자용 트랜스폼 영상입니다.": "يرجى تحميل صورة واحدة جيدة فقط. هذا فيديو تحويلي للمبتدئين يحول الصور اليومية العادية إلى معالم خارجية وأحاسيس على Instagram وأمزجة عارضات الأزياء.",
    "01 · Travel Jump": "01 · قفزة السفر",
    "해외 명소로 순간 이동": "النقل الفوري إلى مناطق الجذب في الخارج",
    "앉아 있던 사진도 파리, 뉴욕, 산토리니, 도쿄 같은 글로벌 무드 영상으로 확장합니다.": "يتم أيضًا توسيع صور الأشخاص الجالسين لتشمل مقاطع فيديو مزاجية عالمية مثل باريس ونيويورك وسانتوريني وطوكيو.",
