    "비율은 9:16 / 16:9 / 1:1 중 선택 가능합니다. 해상도는 플랜별로 제공되며, 4K는 Signature 또는 Custom 플랜에서만 선택 가능합니다.": "يمكن اختيار النسبة من 9:16 / 16:9 / 1:1. يتم توفير الدقة من خلال الخطة، ولا تتوفر دقة 4K إلا في الخطط المميزة أو المخصصة.",
    "납품 일정: Starter 24~48시간, Pro 2~3영업일, Signature 3~5영업일 기준입니다. 이미지 품질, 수정 범위, 4K 여부에 따라 변동될 수 있습니다. 외화 표시는 참고용이며 실제 결제는 원화(KRW)로 진행됩니다.": "جدول التسليم: 24-48 ساعة للمبتدئين، 2-3 أيام عمل للمحترفين، و3-5 أيام عمل للتوقيع. قد يختلف اعتمادًا على جودة الصورة ونطاق التصحيح وتوافر 4K. مؤشرات العملات الأجنبية هي للإشارة فقط؛ يتم الدفع الفعلي بالوون الكوري (KRW).",
    "※ AVVM은 즉시 자동 생성툴이 아니라 고객 이미지 기반 맞춤형 디지털 콘텐츠 제작 서비스입니다. 결제 후 이미지 검토, AI 초안 생성, 품질 검수, 최종 납품 순서로 진행됩니다.": "※ AVVM ليست أداة إنشاء تلقائية فورية، ولكنها خدمة إنشاء محتوى رقمي مخصصة بناءً على صور العملاء. بعد الدفع، تمر العملية بمراجعة الصور وإنشاء مسودة الذكاء الاصطناعي وفحص الجودة والتسليم النهائي.",
    "서비스 제공 기간": "فترة تقديم الخدمة",
    "결제 및 제작자료 접수가 모두 완료된 시점부터 상품별 안내된 제작 기간 내 완성본을 제공합니다.": "من وقت الانتهاء من الدفع ومواد الإنتاج، سيتم توفير المنتج النهائي خلال فترة الإنتاج المحددة لكل منتج.",
    "Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내 제공됩니다.": "سيتم تسليم منتجات Mini·Basic·Best Transform في غضون يوم إلى 3 أيام عمل، وسيتم تسليم 3 مجموعات أنماط في غضون 3 إلى 7 أيام عمل.",
    "Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다.": "سيتم تسليم النسخة المبتدئة خلال 24-48 ساعة، وسيتم تسليم النسخة الاحترافية خلال 2-3 أيام عمل، وسيتم تسليم التوقيع خلال 3-5 أيام عمل.",
    "Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "تخضع منتجات Memorial وID·Profile لفترة عرض تتراوح من 24 إلى 48 ساعة كما هو موضح في كل بطاقة منتج.",
    "고객이 제출한 사진의 품질, 자료 보완, 추가 요청 또는 수정 여부에 따라 일정이 일부 변동될 수 있으며, 지연이 예상되는 경우 고객에게 개별 안내드립니다.": "قد يتغير الجدول اعتمادًا على جودة الصور المقدمة من قبل العميل أو تكملة المواد أو الطلبات الإضافية أو التعديلات. إذا كان من المتوقع حدوث تأخير، فسيتم إخطار العملاء بشكل فردي.",
