    "💡 AI 복원 특성상 실제 모습과 다르게 표현될 수 있으며, 마음에 들지 않을 경우 플랜 기준에 따라 1회 재제작을 도와드립니다. 결과물은 검수 후 전달됩니다.": "💡 نظرًا لطبيعة استعادة الذكاء الاصطناعي، فقد يتم التعبير عنها بشكل مختلف عن مظهرها الفعلي، وإذا لم تعجبك، فسنساعدك على إعادة إنشائها مرة واحدة وفقًا لمعايير الخطة. يتم تسليم النتائج بعد الفحص.",
    "업로드하는 가족·반려동물·고인 사진에 대한 사용 권한이 고객 본인에게 있어야 하며, 제3자의 초상권·저작권·명예를 침해하는 요청은 제작이 제한될 수 있습니다.": "يجب أن يحصل العميل على إذن لاستخدام الصور التي تم تحميلها للعائلة أو الحيوانات الأليفة أو المتوفى، وقد يتم تقييد الإنتاج للطلبات التي تنتهك حقوق الصور أو حقوق الطبع والنشر أو سمعة الطرف الثالث.",
