    "취업/사원증/비즈니스 고급 보정": "التوظيف/معرف الموظف/التصحيح المتقدم للأعمال",
    "피부, 대칭, 조명 등 1:1 디테일 고급 보정": "تصحيح متقدم مفصل بنسبة 1:1 للبشرة، والتماثل، والإضاءة، وما إلى ذلك.",
    "48시간 내 전달": "التسليم خلال 48 ساعة",
    "💡 여권, 주민등록증, 운전면허증 등 공식 신분증 사진은 각 기관의 심사 기준에 따라 승인 여부가 달라질 수 있습니다. AVVM은 원본 사진을 기준으로 규격 맞춤, 크롭, 용량 조정, 자연스러운 보정을 지원하며 최종 접수 승인을 보장하지 않습니다.": "💡 قد تختلف الموافقة على صور الهوية الرسمية مثل جواز السفر وبطاقة تسجيل الإقامة ورخصة القيادة وما إلى ذلك حسب معايير الفحص لكل وكالة. يدعم AVVM التخصيص والاقتصاص وتعديل السعة والتصحيح الطبيعي استنادًا إلى الصورة الأصلية ولا يضمن الموافقة النهائية على الإرسال.",
    "타인 사칭, 신원 왜곡, 연령 변경, 얼굴 교체, 실제 인물과 다른 신분 생성 목적의 편집은 진행하지 않습니다. 촬영 상태(초점, 조명, 배경)가 기준에 크게 미달하는 원본은 제작이 어려울 수 있으며, 이 경우 전액 환불됩니다.": "نحن لا نقوم بالتحرير بغرض انتحال شخصية شخص آخر، أو تشويه الهوية، أو تغيير العمر، أو استبدال الوجه، أو إنشاء هوية مختلفة عن الشخص الفعلي. قد يكون من الصعب إنتاج المستندات الأصلية التي تكون ظروف التصوير (التركيز والإضاءة والخلفية) أقل بكثير من المعايير، وفي هذه الحالة سيتم استرداد المبلغ المدفوع بالكامل.",
    "SISTER BRAND · WEB-STUDIO": "العلامة التجارية الشقيقة · استوديو الويب",
