    "사업자등록번호: 347-37-01807 · 통신판매업 신고번호: 제2026-경기파주-2862호": "رقم تسجيل الأعمال: 347-37-01807 · رقم تقرير أعمال الطلب عبر البريد: 2026-Gyeonggi Paju-2862",
    "대표 연락처: 0505-007-5221 · 이메일: airyoon72@naver.com · 도메인: avvm.studio": "رقم الاتصال التمثيلي: 0505-007-5221 · البريد الإلكتروني: airyoon72@naver.com · النطاق: avvm.studio",
    "사업장 주소: 경기도 파주시 미래로310번길 182-37 B동 2층 02호": "عنوان العمل: غرفة 02، المبنى B، الطابق الثاني، 182-37 Mirae-ro 310beon-gil، Paju-si، Gyeonggi-do",
    "본 서비스는 실물 배송이 없는 맞춤형 디지털 콘텐츠 제작 서비스이며, 결제는 원화(KRW)로 처리됩니다.": "هذه الخدمة عبارة عن خدمة إنشاء محتوى رقمي مخصص دون التسليم الفعلي، وتتم معالجة الدفع بالوون الكوري (KRW).",
    "서비스 제공 기간: 결제 및 제작자료 접수가 모두 완료된 시점부터 Mini·Basic·Best Transform 상품은 영업일 기준 1~3일 이내, 3 Style Set은 영업일 기준 3~7일 이내, Starter는 24~48시간, Pro는 영업일 기준 2~3일, Signature는 영업일 기준 3~5일 이내 제공됩니다. Memorial 및 ID·Profile 상품은 각 상품 카드에 표시된 24~48시간의 제공 기간이 적용됩니다.": "فترة تقديم الخدمة: من وقت اكتمال الدفع ومواد الإنتاج، سيتم توفير منتجات Mini·Basic·Best Transform في غضون يوم إلى 3 أيام عمل، وسيتم توفير 3 مجموعات أنماط في غضون 3 إلى 7 أيام عمل، وسيتم توفير Starter في غضون 24 إلى 48 ساعة، وسيتم توفير Pro في غضون 2 إلى 3 أيام عمل، وسيتم توفير Signature في غضون 3 إلى 5 أيام عمل. تخضع منتجات Memorial وID·Profile لفترة عرض تتراوح من 24 إلى 48 ساعة كما هو موضح في كل بطاقة منتج.",
    "결제대행 및 개인정보 처리 위탁: 주식회사 코리아포트원(전자결제 서비스 제공, 결제 처리, 결제 결과 확인 및 정산 업무)": "وكالة الدفع ومعالجة المعلومات الشخصية المكلف بها: شركة Korea Port One Co., Ltd. (توفير خدمة الدفع الإلكتروني، ومعالجة الدفع، وتأكيد نتائج الدفع وتسويتها)",
