    "스타트 버튼을 누른 뒤 바로 결제 정보가 아니라, 원하는 상품을 먼저 고르는 흐름입니다.": "بعد الضغط على زر البداية، تقوم أولاً بتحديد المنتج الذي تريده، بدلاً من إدخال معلومات الدفع.",
