    "4대 규격 전체 패키지 (여권/주민증/면허/이력서)": "حزمة كاملة من 4 مواصفات رئيسية (جواز السفر/بطاقة الإقامة/الترخيص/السيرة الذاتية)",
    "PRO": "للمحترفين",
    "Selected plan: Pro · ₩39,900": "الخطة المختارة: Pro · ₩39,900",
    "1. 제작할 사진 업로드": "1. قم بتحميل الصورة التي تريد إنشاءها",
    "고객님의 사진 또는 상품 이미지를 첨부해 주세요. 지금 첨부하지 않아도 결제 후 업로드할 수 있습니다.": "يرجى إرفاق صورتك أو صورة المنتج. حتى لو لم تقم بإرفاقه الآن، يمكنك تحميله بعد الدفع.",
    "사진 첨부하기": "إرفاق صورة",
    "JPG, PNG, WEBP 등 이미지 파일": "ملفات الصور مثل JPG، PNG، WEBP، إلخ.",
